-- Vietnam: ES/DE/FR milestone translations for migration 289's 4
-- milestones. Real translations (not the English text copy-pasted),
-- following the same INSERT OR IGNORE pattern as every other
-- country's milestone_translations migration this session.

-- ---- es ----
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('vn-decree-123-2020', 'es', 'El Decreto 123/2020/ND-CP establece el marco de facturación electrónica de Vietnam', 'El gobierno emitió el Decreto 123/2020/ND-CP, el marco legal principal que establece la facturación electrónica obligatoria en Vietnam, junto con la guía de aplicación que siguió en la Circular 78/2021/TT-BTC. Este decreto sustituyó al Decreto 119/2018/ND-CP de 2018, cuyo plazo original había sido aplazado, y sentó las bases técnicas y legales -- facturas XML estructuradas, verificación por la autoridad tributaria y una implantación por fases -- para el mandato nacional que llegó en 2022.', '["Aún no se requiere ninguna acción -- este decreto sienta las bases legales del mandato que se implanta a continuación", "Las empresas de las provincias piloto (Hanói, Ciudad Ho Chi Minh) deben empezar a seguir las indicaciones de la GDT antes del piloto"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('vn-pilot-2021', 'es', 'Comienza la fase piloto en Hanói y Ciudad Ho Chi Minh', 'La Dirección General de Tributación (GDT) puso en marcha una implementación piloto del marco de facturación electrónica del Decreto 123 en seis provincias y ciudades, entre ellas Hanói y Ciudad Ho Chi Minh, antes del mandato nacional. Las empresas de las zonas piloto empezaron a abandonar las facturas en papel y a probar los dos modelos de transmisión del mandato: la compensación en tiempo real con un código de la autoridad tributaria y la notificación el mismo día sin código.', '["Las empresas de las seis provincias/ciudades piloto deben registrarse ante la GDT y elegir ya una vía de integración, antes del plazo nacional", "En el resto del país: sigan las indicaciones de la GDT, ya que el mandato nacional llega en pocos meses"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('vn-mandate-2022', 'es', 'La facturación electrónica se vuelve obligatoria en todo el país; las facturas en papel dejan de ser válidas', 'A partir de esta fecha, las facturas electrónicas estructuradas se volvieron obligatorias para todas las empresas registradas, hogares empresariales y autónomos bajo el método de declaración en todo Vietnam, abarcando las ventas nacionales B2B, B2C minoristas, B2G y de exportación. Las facturas en papel dejaron de tener validez legal a efectos del IVA. Coexisten dos modelos de transmisión: la compensación en tiempo real con un código emitido por la GDT obtenido antes o en el momento de la emisión, o la notificación el mismo día sin código, transmitida a la GDT a más tardar el día en que se entrega la factura.', '["Confirmen que su empresa ha elegido e integrado una solución de facturación electrónica -- API directa, software propio o un proveedor de servicios certificado", "Determinen si sus facturas necesitan el código de la autoridad tributaria (compensación en tiempo real) o entran en el modelo de notificación el mismo día, y adapten sus sistemas en consecuencia", "Eliminen cualquier proceso de facturación en papel que quede -- ya no tiene validez legal a efectos del IVA"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('vn-decree-70-2025', 'es', 'El Decreto 70/2025 amplía el mandato a los proveedores extranjeros de comercio electrónico y a los grandes hogares empresariales', 'El Decreto 70/2025/ND-CP modificó el Decreto 123, incorporando al ámbito de aplicación a los hogares empresariales y autónomos con una facturación anual de 1.000 millones de VND (unos 38.000 USD) o más, que deben emitir facturas electrónicas desde cajas registradoras (POS) conectadas en tiempo real a la GDT, junto con los sectores de cara al consumidor (centros comerciales, supermercados, restaurantes, hoteles, transporte de pasajeros y servicios personales) sin importar su nivel de facturación. Los proveedores extranjeros de comercio electrónico y de servicios digitales sin establecimiento permanente en Vietnam ya pueden registrarse para emitir facturas de IVA vietnamitas directamente, y el decreto uniformó los plazos de emisión de facturas según el tipo de operación (bienes, servicios, exportaciones, suministros).', '["Hogares empresariales y autónomos por encima del umbral de 1.000 millones de VND: registren un sistema POS conectado a la GDT si aún no lo han hecho", "Empresas de cara al consumidor (comercio minorista, hostelería, transporte, servicios personales): confirmen el cumplimiento de la facturación electrónica por POS independientemente de su nivel de facturación", "Proveedores extranjeros de servicios digitales: evalúen registrarse para la facturación de IVA vietnamita directamente bajo la nueva disposición"]');

-- ---- de ----
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('vn-decree-123-2020', 'de', 'Dekret 123/2020/ND-CP legt Vietnams E-Invoicing-Rahmen fest', 'Die Regierung erließ das Dekret 123/2020/ND-CP, den zentralen Rechtsrahmen für die verpflichtende elektronische Rechnungsstellung in Vietnam, ergänzt durch die spätere Durchführungsrichtlinie Circular 78/2021/TT-BTC. Dieses Dekret ersetzte das Dekret 119/2018/ND-CP von 2018, dessen ursprüngliche Frist verschoben worden war, und legte die technische und rechtliche Grundlage -- strukturierte XML-Rechnungen, Prüfung durch die Steuerbehörde und ein stufenweises Vorgehen -- für die landesweite Pflicht fest, die 2022 folgte.', '["Noch keine Maßnahme erforderlich -- dieses Dekret legt die rechtliche Grundlage für die unten beschriebene Pflicht fest", "Unternehmen in den Pilotprovinzen (Hanoi, Ho-Chi-Minh-Stadt) sollten die Hinweise der GDT vor dem Pilotprojekt verfolgen"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('vn-pilot-2021', 'de', 'Pilotphase beginnt in Hanoi und Ho-Chi-Minh-Stadt', 'Die vietnamesische Steuerbehörde (General Department of Taxation, GDT) startete vor der landesweiten Pflicht eine Pilotumsetzung des E-Invoicing-Rahmens aus Dekret 123 in sechs Provinzen und Städten, darunter Hanoi und Ho-Chi-Minh-Stadt. Unternehmen in den Pilotgebieten stellten schrittweise von Papierrechnungen um und testeten beide Übermittlungsmodelle der Pflicht -- Echtzeit-Freigabe mit einem Code der Steuerbehörde und tagesgleiche Meldung ohne Code.', '["Unternehmen in den sechs Pilotprovinzen/-städten sollten sich jetzt bei der GDT registrieren und einen Integrationsweg wählen, vor der landesweiten Frist", "Überall sonst: die Hinweise der GDT verfolgen, da die landesweite Pflicht innerhalb weniger Monate folgt"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('vn-mandate-2022', 'de', 'E-Invoicing wird landesweit verpflichtend; Papierrechnungen verlieren ihre Gültigkeit', 'Ab diesem Datum wurden strukturierte E-Rechnungen für alle registrierten Unternehmen, Gewerbehaushalte und Einzelunternehmer im Deklarationsverfahren in ganz Vietnam verpflichtend -- einschließlich inländischer B2B-, B2C-Einzelhandels-, B2G- und Exportumsätze. Papierrechnungen verloren ihre umsatzsteuerliche Gültigkeit. Zwei Übermittlungsmodelle bestehen nebeneinander: Echtzeit-Freigabe mit einem von der GDT ausgestellten Code, der vor oder im Moment der Ausstellung eingeholt wird, oder tagesgleiche Meldung ohne Code, die spätestens am Tag der Rechnungslieferung an die GDT übermittelt wird.', '["Bestätigen Sie, dass Ihr Unternehmen eine E-Invoicing-Lösung gewählt und integriert hat -- direkte API, eigene Software oder ein zertifizierter Dienstleister", "Bestimmen Sie, ob Ihre Rechnungen den Code der Steuerbehörde benötigen (Echtzeit-Freigabe) oder unter das tagesgleiche Meldemodell fallen, und richten Sie Ihre Systeme entsprechend aus", "Stellen Sie verbliebene Papierrechnungsprozesse ein -- sie haben umsatzsteuerlich keine Gültigkeit mehr"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('vn-decree-70-2025', 'de', 'Dekret 70/2025 weitet die Pflicht auf ausländische E-Commerce-Anbieter und große Gewerbehaushalte aus', 'Das Dekret 70/2025/ND-CP änderte Dekret 123 und nahm Gewerbehaushalte und Einzelunternehmer mit einem Jahresumsatz von 1 Milliarde VND (rund 38.000 USD) oder mehr in den Anwendungsbereich auf: Sie benötigen POS-Registrierkassen mit E-Rechnung, die in Echtzeit mit der GDT verbunden sind, ebenso wie verbraucherorientierte Branchen (Einkaufszentren, Supermärkte, Restaurants, Hotels, Personenverkehr und persönliche Dienstleistungen) unabhängig von der Umsatzhöhe. Ausländische E-Commerce- und Digitaldienstanbieter ohne dauerhafte Niederlassung in Vietnam können sich nun registrieren, um direkt vietnamesische Umsatzsteuerrechnungen auszustellen, und das Dekret vereinheitlichte die Fristen für die Rechnungsstellung je nach Transaktionsart (Waren, Dienstleistungen, Exporte, Versorgungsleistungen).', '["Gewerbehaushalte und Einzelunternehmer oberhalb der Schwelle von 1 Milliarde VND: registrieren Sie, falls noch nicht geschehen, ein mit der GDT verbundenes POS-System", "Verbraucherorientierte Unternehmen (Einzelhandel, Gastgewerbe, Verkehr, persönliche Dienstleistungen): bestätigen Sie die POS-E-Invoicing-Konformität unabhängig von Ihrer Umsatzhöhe", "Ausländische Anbieter digitaler Dienstleistungen: prüfen Sie eine direkte Registrierung für die vietnamesische Umsatzsteuer-Rechnungsstellung nach der neuen Regelung"]');

-- ---- fr ----
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('vn-decree-123-2020', 'fr', 'Le décret 123/2020/ND-CP établit le cadre de facturation électronique du Viêt Nam', 'Le gouvernement a publié le décret 123/2020/ND-CP, le cadre juridique principal instaurant la facturation électronique obligatoire au Viêt Nam, complété par la circulaire d''application 78/2021/TT-BTC. Ce décret a remplacé le décret 119/2018/ND-CP de 2018, dont l''échéance initiale avait été reportée, et a posé les bases techniques et juridiques -- factures XML structurées, vérification par l''administration fiscale et déploiement progressif -- de l''obligation nationale entrée en vigueur en 2022.', '["Aucune action requise pour l''instant -- ce décret pose les bases juridiques de l''obligation détaillée ci-dessous", "Les entreprises des provinces pilotes (Hanoï, Hô-Chi-Minh-Ville) doivent commencer à suivre les indications de la GDT avant le lancement pilote"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('vn-pilot-2021', 'fr', 'La phase pilote démarre à Hanoï et à Hô-Chi-Minh-Ville', 'L''administration fiscale vietnamienne (General Department of Taxation, GDT) a lancé une mise en œuvre pilote du cadre de facturation électronique du décret 123 dans six provinces et villes, dont Hanoï et Hô-Chi-Minh-Ville, avant l''obligation nationale. Les entreprises des zones pilotes ont commencé à abandonner les factures papier et à tester les deux modèles de transmission de l''obligation -- validation en temps réel avec un code de l''administration fiscale, et déclaration le jour même sans code.', '["Les entreprises des six provinces/villes pilotes doivent s''enregistrer auprès de la GDT et choisir dès maintenant une voie d''intégration, avant l''échéance nationale", "Ailleurs : suivre les indications de la GDT, l''obligation nationale arrivant dans les mois qui suivent"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('vn-mandate-2022', 'fr', 'La facturation électronique devient obligatoire dans tout le pays ; les factures papier perdent leur validité', 'À partir de cette date, les factures électroniques structurées sont devenues obligatoires pour toutes les entreprises enregistrées, les foyers d''entreprise et les entrepreneurs individuels soumis au régime déclaratif dans tout le Viêt Nam, couvrant les ventes B2B domestiques, B2C au détail, B2G et à l''exportation. Les factures papier ont perdu toute validité légale au regard de la TVA. Deux modèles de transmission coexistent : la validation en temps réel avec un code délivré par la GDT obtenu avant ou au moment de l''émission, ou la déclaration le jour même sans code, transmise à la GDT au plus tard le jour de la livraison de la facture.', '["Vérifiez que votre entreprise a choisi et intégré une solution de facturation électronique -- API directe, logiciel interne ou prestataire certifié", "Déterminez si vos factures nécessitent le code de l''administration fiscale (validation en temps réel) ou relèvent du modèle de déclaration le jour même, et adaptez vos systèmes en conséquence", "Abandonnez tout processus de facturation papier restant -- il n''a plus de validité légale au regard de la TVA"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('vn-decree-70-2025', 'fr', 'Le décret 70/2025 étend l''obligation aux fournisseurs étrangers de commerce électronique et aux grands foyers d''entreprise', 'Le décret 70/2025/ND-CP a modifié le décret 123, faisant entrer dans le champ d''application les foyers d''entreprise et entrepreneurs individuels réalisant un chiffre d''affaires annuel de 1 milliard de VND (environ 38 000 USD) ou plus, désormais tenus d''utiliser des caisses enregistreuses (POS) émettant des factures électroniques connectées en temps réel à la GDT, aux côtés des secteurs en contact direct avec les consommateurs (centres commerciaux, supermarchés, restaurants, hôtels, transport de voyageurs et services à la personne) quel que soit leur chiffre d''affaires. Les fournisseurs étrangers de commerce électronique et de services numériques sans établissement permanent au Viêt Nam peuvent désormais s''enregistrer pour émettre directement des factures de TVA vietnamiennes, et le décret a harmonisé les délais d''émission des factures selon le type d''opération (biens, services, exportations, services collectifs).', '["Foyers d''entreprise et entrepreneurs individuels au-dessus du seuil de 1 milliard de VND : enregistrez un système POS connecté à la GDT si ce n''est pas déjà fait", "Entreprises en contact avec les consommateurs (commerce de détail, hôtellerie, transport, services à la personne) : vérifiez votre conformité en matière de facturation électronique par POS, quel que soit votre chiffre d''affaires", "Fournisseurs étrangers de services numériques : envisagez de vous enregistrer pour la facturation de TVA vietnamienne directement dans le cadre de la nouvelle disposition"]');
